#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int *items = malloc(2 * sizeof *items);
    if (items == NULL) {
        return 1;
    }
    items[0] = 10;
    items[1] = 20;
    int *next = realloc(items, 4 * sizeof *items);
    if (next == NULL) {
        free(items);
        return 1;
    }
    items = next;
    items[2] = 30;
    items[3] = 40;
    printf("%d %d\n", items[0], items[3]);
    free(items);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int *items = malloc(4 * sizeof *items);
    if (items == NULL) {
        return 1;
    }
    for (int i = 0; i < 4; i++) {
        items[i] = (i + 1) * 5;
    }
    int *next = realloc(items, 2 * sizeof *items);
    if (next == NULL) {
        free(items);
        return 1;
    }
    items = next;
    printf("%d %d\n", items[0], items[1]);
    free(items);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int *owner = malloc(sizeof *owner);
    if (owner == NULL) {
        return 1;
    }
    *owner = 25;
    printf("Before: %d\n", *owner);
    free(owner);
    owner = NULL;
    free(owner);
    printf("Empty: %d\n", owner == NULL);
    return 0;
}

